WITH unpacked AS (SELECT id, plan, effective_from, currency, tier_limits, tier_prices, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT DATE_TRUNC('WEEK', effective_from) AS week_start, currency, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list, COUNT(*) AS row_count, SUM(CASE WHEN plan = 'enterprise' THEN avg_tier_price ELSE 0 END) AS enterprise_avg_tier_price FROM unpacked GROUP BY 1, 2
